import { describe, expect, it } from "vitest";
import { ConversationEventType, type Skill, type UnionEventType } from "../../types";
import { deriveSkillStateAt } from "./deriveSkillStateAt";

const skill: Skill = {
  id: "card_replace",
  name: "Card Replace",
  description: null,
  is_default: false,
  engine_managed: false,
  disabled: false,
  sections: [],
  blocks: {
    main: {
      ordered_block_id: "card_replace__main",
      complete_when: null,
      steps: [],
    },
    submit: {
      ordered_block_id: "card_replace__submit",
      complete_when: null,
      steps: [],
    },
  },
  referenced_skills: [],
  tool_names: [],
  hidden: false,
};

function event(
  overrides: Record<string, unknown> & { conversationEventType: string },
): UnionEventType {
  return {
    __typename: "ConversationEvent",
    id: "evt",
    metadata: { parseData: undefined },
    timestamp: new Date().toISOString(),
    originalTimestamp: 0,
    slotValue: null,
    ...overrides,
  } as UnionEventType;
}

describe("deriveSkillStateAt block replay", () => {
  it("marks a block entered at the anchor as active", () => {
    const events = [
      event({
        id: "e0",
        conversationEventType: ConversationEventType.SkillActivated,
        skillId: "card_replace",
      }),
      event({
        id: "e1",
        conversationEventType: ConversationEventType.OrderedBlockEntered,
        skillId: "card_replace",
        blockId: "main",
      }),
    ];
    const state = deriveSkillStateAt(events, 1, "card_replace", skill);
    expect(state.blocks["card_replace__main"]?.status).toBe("active");
  });

  it("keeps a block active at the anchor even though it completes later", () => {
    const events = [
      event({
        id: "e0",
        conversationEventType: ConversationEventType.OrderedBlockEntered,
        skillId: "card_replace",
        blockId: "main",
      }),
      event({
        id: "e1",
        conversationEventType: ConversationEventType.OrderedBlockCompleted,
        skillId: "card_replace",
        blockId: "main",
      }),
    ];
    // Anchor at the entered event (index 0): the later completion must not leak in.
    const atEntered = deriveSkillStateAt(events, 0, "card_replace", skill);
    expect(atEntered.blocks["card_replace__main"]?.status).toBe("active");
    // Anchor at the completion (index 1): now completed.
    const atCompleted = deriveSkillStateAt(events, 1, "card_replace", skill);
    expect(atCompleted.blocks["card_replace__main"]?.status).toBe("completed");
  });

  it("maps cancelled and interrupted blocks to inactive", () => {
    const cancelled = deriveSkillStateAt(
      [
        event({
          conversationEventType: ConversationEventType.OrderedBlockCancelled,
          skillId: "card_replace",
          blockId: "main",
        }),
      ],
      0,
      "card_replace",
      skill,
    );
    expect(cancelled.blocks["card_replace__main"]?.status).toBe("inactive");
  });

  it("ignores block events belonging to other skills", () => {
    const events = [
      event({
        conversationEventType: ConversationEventType.OrderedBlockEntered,
        skillId: "other_skill",
        blockId: "main",
      }),
    ];
    const state = deriveSkillStateAt(events, 0, "card_replace", skill);
    expect(state.blocks).toEqual({});
  });
});

describe("deriveSkillStateAt memory replay", () => {
  it("applies set/clear writes in order up to the anchor", () => {
    const events = [
      event({
        id: "m0",
        conversationEventType: ConversationEventType.MemorySet,
        name: "card_replace.reason",
        value: "lost",
      }),
      event({
        id: "m1",
        conversationEventType: ConversationEventType.MemorySet,
        name: "card_replace.reason",
        value: "stolen",
      }),
      event({
        id: "m2",
        conversationEventType: ConversationEventType.MemoryCleared,
        name: "card_replace.reason",
      }),
    ];
    // At m1 the latest value is "stolen".
    expect(
      deriveSkillStateAt(events, 1, "card_replace", skill).memory["card_replace.reason"],
    ).toEqual({
      value: "stolen",
    });
    // At m2 it is cleared to null.
    expect(
      deriveSkillStateAt(events, 2, "card_replace", skill).memory["card_replace.reason"],
    ).toEqual({
      value: null,
    });
  });

  it("replays memory across all scopes, not just the anchored skill", () => {
    const events = [
      event({
        conversationEventType: ConversationEventType.MemorySet,
        name: "project.selected_card_id",
        value: "card-1",
      }),
    ];
    const state = deriveSkillStateAt(events, 0, "card_replace", skill);
    expect(state.memory["project.selected_card_id"]).toEqual({ value: "card-1" });
  });
});

describe("deriveSkillStateAt position", () => {
  it("takes the anchor's own flow/step when it carries one", () => {
    const events = [
      event({
        conversationEventType: "ACTION",
        skillId: "card_replace",
        flowId: "card_replace__main",
        stepId: "collect",
      }),
    ];
    const state = deriveSkillStateAt(events, 0, "card_replace", skill);
    expect(state.position).toEqual({ flowId: "card_replace__main", stepId: "collect" });
  });

  it("falls back to the latest step-bearing event when the anchor has no step", () => {
    const events = [
      event({
        id: "s0",
        conversationEventType: ConversationEventType.OrderedBlockEntered,
        skillId: "card_replace",
        blockId: "main",
        flowId: "card_replace__main",
        stepId: "collect",
      }),
      // The anchor is a memory write carrying no step.
      event({
        id: "s1",
        conversationEventType: ConversationEventType.MemorySet,
        name: "card_replace.reason",
        value: "lost",
      }),
    ];
    const state = deriveSkillStateAt(events, 1, "card_replace", skill);
    expect(state.position).toEqual({ flowId: "card_replace__main", stepId: "collect" });
  });
});
